@startuml

class School {
  +name : string
}

class Teacher {
  +firstName : string
  +lastName : string
  +email : string
}

class Student {
  +firstName : string
  +lastName : string
}

class Room {
}

class Classroom extends Room {
  +name : string
  +capacity : int
}

class Gym extends Room {
  +name : string
  +size : float
}

class ClassGroup {
  +name : string
}

class TeachingAssignment {
  +hours : int
}

School "1" -- "1" Teacher : principal
School "1" -- "*" Teacher : employs
Teacher "1..3" -- "0..*" School : teaches
Teacher "1" -- "*" TeachingAssignment
School "1" -- "*" TeachingAssignment
Classroom "1" -- "1" ClassGroup : assigned to
ClassGroup "1" -- "10..31" Student : contains
Student "1" -- "1" ClassGroup : belongs to

@enduml

